INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68057, 'spa', 'Proclamar cosas ocultas', 'Mateo 13:35 cita la promesa del salmista de proferir cosas ocultas: parábolas que revelan misterios guardados por largo tiempo. Los glosarios interlingüísticos privilegian los sentidos proclamatorios (proclamar, declarar) sobre el original ''mugir/bramar'', mostrando cómo la Septuaginta espiritualizó esta palabra. La imagen del mar rugiendo subyace en esta proclamación solemne.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68058, 'spa', 'Escudriñar, investigar', 'Buscar con detenimiento, examinar a fondo o investigar con esmero, implicando una indagación profunda y no un repaso superficial. Se usa del Espíritu que escudriña las profundidades de Dios (1 Co 2:10), de Dios que escudriña los corazones humanos (Ro 8:27), de los creyentes que examinan las Escrituras (Jn 5:39) y de los profetas que investigaron cuidadosamente la salvación que anunciaron (1 P 1:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68063, 'spa', 'decir, hablar', 'El sentido activo primario: decir, hablar o comunicar algo a alguien. Cubre toda aparición en voz activa: declaraciones, mandatos, predicciones y diálogos. En Mateo 21:3 Jesús instruye a los discípulos que digan ''El Señor los necesita,'' y en Mateo 7:22 aparece en declaración escatológica. La amplitud de formas flexionadas (futuro, perfecto, aoristo) muestra que era el verbo de discurso cotidiano por excelencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68064, 'spa', 'lo que fue dicho', 'El sentido pasivo empleado en fórmulas de cumplimiento profético y citas: ''lo que fue dicho'' o ''se dijo.'' Muy concentrado en Mateo (1:22; 2:15, 17, 23; 3:3), este uso enmarca la profecía veterotestamentaria como discurso divinamente pronunciado que ahora alcanza su objetivo. La construcción pasiva eleva la declaración misma: no son meras palabras humanas sino un pronunciamiento autoritativo que se cumple.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68088, 'spa', 'llamar, designar', 'Una única aparición en Juan 15:15 donde Jesús dice ''Os he llamado amigos,'' empleando este verbo en una declaración performativa que confiere estatus, en lugar de un simple informe. La fuerza de nombrar o designar convierte esto en un acto de habla que transforma la relación, más allá de la mera transmisión de información.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68090, 'spa', 'Desierto inhabitado', 'Región desolada y despoblada, un yermo o desierto lejos de todo asentamiento y provisión humana. Los relatos de la alimentación milagrosa (Mt 15:33; Mc 8:4) subrayan la imposibilidad de hallar pan en tal vacío. Pablo la cataloga entre los peligros mortales de sus viajes misioneros (2 Co 11:26), y Hebreos 11:38 honra a los fieles que fueron empujados a desiertos y montañas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68091, 'spa', 'desierto (sustantivo geográfico)', 'Uso sustantivado en que ἔρημος designa un lugar geográfico concreto: «el desierto». Es el desierto de los cuarenta años de Israel, el yermo del Jordán donde Juan bautizaba (Mt 3:1-3) y el escenario de la tentación de Jesús (Mt 4:1). Con 36 apariciones domina el uso neotestamentario. Todas las tradiciones lo vierten con un sustantivo propio: desierto, désert, Wüste.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68092, 'spa', 'lugar desolado o solitario', 'Sentido adjetival que describe un lugar como desierto, remoto o deshabitado. Jesús «se retiró a un lugar desierto» (Mt 14:13); los discípulos advierten «este es un lugar desierto» (Mc 6:31). El énfasis recae en la cualidad de vacío y soledad, no en la identidad geográfica. El contexto y la sintaxis distinguen este uso del sustantivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68095, 'spa', 'desolado, abandonado (profético)', 'Sentido metafórico y profético de abandono. La sentencia de Jesús —«vuestra casa os es dejada desierta» (Mt 23:38)— evoca juicio divino. Pablo cita a Isaías: «la desolada tiene más hijos» (Gá 4:27), y Pedro aplica el Salmo 69 a la morada abandonada de Judas (Hch 1:20). Desolada y desierta marcan este registro profético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68099, 'spa', 'Devastar o asolar', 'Asolar, devastar, reducir a ruina: llevar un lugar o institución de la prosperidad a la vacuidad y destrucción. Jesús lo aplica a la división interna que destruye cualquier reino u hogar (Matt 12:25; Luke 11:17). En Apocalipsis describe el juicio que aniquila a Babilonia la Grande (Rev 17:16; Rev 18:17, 19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68100, 'spa', 'Desolación devastadora', 'Las tres apariciones citan la «abominación desoladora» de Daniel: Mateo 24:15 advierte «cuando veáis la abominación desoladora de que habló el profeta Daniel»; Marcos 13:14 contiene la misma advertencia con el énfasis «el que lee, entienda»; y Lucas 21:20 lo interpreta como «cuando veáis a Jerusalén rodeada de ejércitos», vinculando la desolación con la destrucción histórica del templo y el juicio final.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68101, 'spa', 'Contender o disputar', 'La profecía de Isaías (citada en Mateo 12:19) de que el Siervo no contenderá ni disputará describe su ministerio manso y pacífico. La consistencia interlingüística (contender, disputar, porfiar) muestra reconocimiento universal de este término como conflicto. El uso clásico abarcaba competencias atléticas, discusiones verbales y guerras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68102, 'spa', 'Ambición egoísta, rivalidad', 'Ambición egoísta, rivalidad facciosa o partidismo interesado. Originalmente designaba el trabajo mercenario por salario; luego pasó al proselitismo político y de ahí a toda disposición que busca el avance propio mediante la contienda de bandos. Pablo la incluye entre las obras de la carne (Gá 5:20) y advierte contra ella en Filipenses 1:17 y 2:3.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68108, 'spa', 'Contienda, discordia', 'Contienda, riña o rivalidad contenciosa entre personas, que aparece constantemente en las listas paulinas de vicios como marca de una conducta carnal e inmadura. Nombra el espíritu de facción y disputa que desgarra comunidades, figurando junto a los celos (ζῆλος), la ira (θυμός) y la ambición egoísta (ἐριθεία) en Gá 5:20 y 2 Co 12:20. En Corinto, ἔρις era el síntoma visible de inmadurez espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68114, 'spa', 'Cabrito o chivo joven', 'La parábola del juicio (Mateo 25:33) utiliza la tarea del pastor de separar ovejas de cabras para ilustrar la separación final entre justos e injustos. Los glosarios interlingüísticos (cabritos, chivos jóvenes) especifican cabras pequeñas o jóvenes, aunque el diminutivo puede ser simplemente léxico. El contexto presupone rebaños mixtos, algo cotidiano en el Mediterráneo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68116, 'spa', 'Nombre propio cristiano', 'El saludo de Pablo a Hermas en Romanos 16:14 es nuestra única referencia neotestamentaria a este cristiano en Roma. La evidencia interlingüística muestra transliteración con ajuste fonológico menor (Hermas, Hermán, Hermès). La conexión con Hermes (dios griego) no era llamativa en la cultura grecorromana, donde los nombres teofóricos eran habituales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68118, 'spa', 'Traducir e interpretar', 'Juan 1:42 dice «Cefas (que traducido es Pedro)»; Juan 9:7 explica «Siloé (que traducido es Enviado)»; y Hebreos 7:2 presenta «Melquisedec, que significa rey de justicia, y también rey de Salem, es decir, rey de paz». En cada caso el verbo sirve como puente lingüístico que aclara al lector griego el sentido de nombres semíticos con carga teológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68120, 'spa', 'Nombre propio masculino', 'La mención de Hermógenes en 2 Timoteo 1:15 como uno de los que abandonaron a Pablo registra una dolorosa deserción: este hombre y Figelo representan la defección más amplia de los creyentes en Asia. Las glosas interlingüísticas simplemente transliteran el nombre (Hermogenes, Hermogénēs), como es habitual con los nombres propios. El elemento teofórico (nacido de Hermes) era común en la cultura griega.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68121, 'spa', 'Reptiles y rastreros', 'Animales rastreros, reptiles y por extensión toda criatura que se arrastra o repta por el suelo. En la visión de Pedro en la azotea (Hch 10:12; 11:6), los reptiles aparecen junto a cuadrúpedos y aves como criaturas antes impuras que Dios declara limpias. Romanos 1:23 invoca esta categoría para ilustrar la degradación idolátrica, y Santiago 3:7 los menciona entre las fieras que el ser humano ha domesticado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68123, 'spa', 'venir, llegar', 'El sentido básico de movimiento físico hacia una persona o lugar: llegar, acercarse, dirigirse a. Dominante en toda la narrativa evangélica (Mt 8:9; 17:11). El árabe emplea la raíz j-ʾ-ʾ (جاء), el alemán kommt, todos apuntando con claridad a la llegada direccional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68132, 'spa', 'el que viene (mesiánico)', 'El participio sustantivado ὁ ἐρχόμενος (''el que viene'') funciona como título mesiánico y escatológico. Central en la pregunta del Bautista en Mateo 11:3 y la aclamación del Domingo de Ramos en Mateo 21:9. El árabe الآتي (al-aatii) y el coreano 오시는 분 subrayan con formas honoríficas el peso de este título.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68137, 'spa', '¡ven! (imperativo)', 'Usos imperativos que funcionan como llamamiento o invitación: ''¡Ven!'' Jesús llama a Pedro a caminar sobre el agua (Mt 14:29) y la parábola invita a los convidados (Lc 14:17). El árabe emplea una raíz distinta, تعال (taʿaal), para este mandato, revelando una escisión pragmática que el griego deja implícita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68148, 'spa', 'venidero, futuro', 'Uso atributivo-temporal que significa ''venidero, futuro, siguiente,'' modificando un sustantivo de tiempo. El español emplea venidero (''por venir''), distinguiéndolo del sentido verbal. Aparece en expresiones como ''el siglo venidero'' (Mc 10:30; Lc 18:30) y ''las cosas que han de venir'' (Jn 16:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68162, 'spa', 'ir, partir', 'Sentido infrecuente donde ἔρχομαι funciona como ''ir'' o ''partir,'' movimiento de alejamiento en lugar de acercamiento. El coreano distingue 가다 (gada, ''ir'') de 오다 (oda, ''venir''), y el español usa vamos (''vámonos''). Atestiguado en Marcos 1:39 y Juan 21:3, donde la dirección es hacia fuera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68165, 'spa', 'entrar, ir adentro', 'Extensión contextual donde ἔρχομαι significa ''entrar'' o ''ir adentro.'' El árabe emplea la raíz d-kh-l (دخل, ''entrar''), el coreano 들어가다 y el suajili -ingia, todos léxicamente distintos de ''venir.'' Se observa cuando los magos entran en la casa (Mt 2:11) y cuando Jesús entra en la casa de un fariseo (Lc 14:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68180, 'spa', 'preguntar, inquirir', 'Formular una pregunta o interrogar a alguien buscando información. Aparece en escenas de diálogo cuyo fin es comprender, no persuadir: Jesús interroga a sus discípulos (Mt 16:13), plantea una contrapregunta (Mt 21:24) o los discípulos temen preguntar (Lc 9:45). El español emplea sistemáticamente «preguntar», confirmando la distinción semántica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68181, 'spa', 'pedir, rogar, suplicar', 'Hacer una petición, súplica o ruego ferviente —pedir a alguien que haga algo, no solicitar información—. Destaca en pasajes donde se suplica a Jesús sanidad o auxilio (Mc 7:26; Lc 4:38; Lc 5:3). El español distingue con «rogar» y «pedir» frente a «preguntar». El alemán diferencia «bitten» de «fragen».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68214, 'spa', 'Vestidura, indumentaria', 'Prenda exterior o artículo de vestir que típicamente connota distinción, formalidad o esplendor. Cada aparición neotestamentaria destaca ropa que comunica estatus o gloria sobrenatural: los soldados de Herodes visten a Jesús con ropas espléndidas (Lc 23:11), ángeles aparecen en el sepulcro vacío y en la ascensión con vestiduras blancas resplandecientes (Lc 24:4; Hch 1:10), Cornelio ve una figura celestial con ropa brillante (Hch 10:30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68217, 'spa', 'comer alimento', 'Comer o ingerir alimento en sentido ordinario y literal. Esta acepción dominante abarca todas las formas gramaticales en 64 apariciones. Aparece en escenas cruciales: la alimentación de los cinco mil (Mt 14:20-21), la Última Cena y los debates paulinos sobre alimentos sacrificados a ídolos. «Comer», «manger» y «essen» convergen en la ingestión física básica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68234, 'spa', 'consumir, devorar', 'Consumir o devorar de forma destructiva, usado figuradamente para el fuego o el juicio divino. En Hebreos 10:27 se advierte de «un furor de fuego que ha de devorar a los adversarios», donde el verbo adquiere connotación de aniquilación total. El español «devorar» capta este matiz agresivo, mientras «manger» y «essen» mantienen el verbo base y dependen del contexto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68240, 'spa', 'Antepasado de Jesús', 'Lucas 3:25 incluye a Eslí en la genealogía de Jesús entre Naúm y Nagai, un antepasado del cual no sabemos nada más. La variación interlingüística (Hesli, Heslí, Esli) refleja cómo las tradiciones manuscritas preservaron diferentes vocalizaciones de este nombre hebreo. La función de la genealogía es establecer el linaje humano de Jesús, y Eslí cumple ese propósito como un eslabón en la cadena que conecta a Jesús con David y Abraham.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68242, 'spa', 'Atardecer o tarde', 'Lucas 24:29 recoge las palabras de los discípulos de Emaús: «Quédate con nosotros, porque se hace tarde», marcando el fin del día. Hechos 4:3 explica por qué Pedro y Juan fueron detenidos durante la noche: «ya era tarde», demasiado avanzado para una audiencia. Hechos 28:23 describe la extensa sesión de enseñanza de Pablo «desde la mañana hasta la tarde», abarcando todo el día.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68243, 'spa', 'Antepasado genealógico', 'Mateo 1:3 registra dos veces el nombre: «Fares engendró a Hesrón, y Hesrón engendró a Ram» en la genealogía desde Abraham. Lucas 3:33 incluye «Hesrón, hijo de Fares» en la genealogía ascendente desde Jesús hasta Adán. Estas referencias anclan la ascendencia legal de Jesús en la tribu de Judá y la casa de David, cumpliendo las profecías mesiánicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68244, 'spa', 'último, final (temporal)', 'Último o final en una secuencia temporal u ordinal. Esta acepción dominante (52 apariciones) abarca expresiones escatológicas como «últimos días» (Hch 2:17; 2 Ti 3:1), «última trompeta» (1 Co 15:52) y el moralmente cargado «último estado» de una persona (Mt 12:45; 2 P 2:20). «Último», «dernier» y «letzter» lo vierten de forma consistente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68247, 'spa', 'fin, extremo (espacial)', 'El punto más lejano o extremo más distante en el espacio. Solo dos apariciones (Hch 1:8 y 13:47), ambas citando a Isaías, emplean el sentido espacial: «hasta lo último de la tierra». «Fin» y «lo último» distinguen este uso del temporal «último». Este sentido geográfico evoca el uso homérico para los pueblos más remotos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68251, 'spa', 'Al borde de muerte', 'La súplica desesperada de Jairo (Marcos 5:23) de que su hija está ''a punto de morir'' emplea este adverbio en una frase idiomática: ἐσχάτως ἔχει, literalmente ''tiene extremadamente'', pero idiomáticamente ''está in extremis''. Las glosas interlingüísticas interpretan en lugar de traducir literalmente: a punto de muerte, al extremo, captando la fuerza semántica de muerte inminente. La derivación del adverbio a partir de ἔσχατος vincula el sentido de ''último'' con la gravedad extrema.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68252, 'spa', 'Adentro, dentro', 'Dentro, en el interior: marca ya sea un espacio físico interior o la dimensión interna de una persona. Los usos espaciales describen estar físicamente dentro de un edificio o recinto cerrado: Pedro siguiendo a Jesús al interior del patio (Mt 26:58; Mr 14:54), soldados llevando a Jesús adentro del pretorio (Mr 15:16), discípulos reunidos tras puertas cerradas (Jn 20:26) y presos hallados dentro de una cárcel sellada (Hch 5:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68256, 'spa', 'Adverbio que indica ubicación en el interior de algo o movimiento que se origina', 'Adverbio que indica ubicación en el interior de algo o movimiento que se origina desde el interior. Usado físicamente para el interior de objetos (Mt 23:25, el interior de la copa; Ap 5:1, un rollo escrito por dentro) y metafóricamente para la vida interior de una persona (Mr 7:21, los malos pensamientos salen ''de dentro''; Mt 23:27-28, la corrupción interna detrás de la belleza exterior). Aparece prominentemente en la enseñanza de Jesús sobre pureza interior frente a exterior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68261, 'spa', 'Amigo, compañero', 'Las traducciones emplean consistentemente «amigo» o «compañero». Los tres usos son vocativos pronunciados por Jesús en Mateo. En 20:13 el amo responde al trabajador que se queja: «Amigo, no te hago ninguna injusticia.» En 22:12 el rey confronta al invitado sin vestido de boda: «Amigo, ¿cómo entraste aquí sin traje de boda?» En 26:50, con profunda gravedad, Jesús se dirige a Judas en el momento de la traición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68262, 'spa', 'Hablante de lengua extranjera', 'La cita de Pablo en 1 Corintios 14:21 sobre Dios hablando mediante personas de lenguas extranjeras evoca la profecía de Isaías sobre la invasión asiria: extranjeros cuyo idioma incomprensible era en sí mismo señal de juicio. Las glosas interlingüísticas enfatizan la diversidad lingüística (otras lenguas, other tongues) o el habla foránea (anderssprachig). El punto teológico conecta con las lenguas en Corinto: así como el habla ininteligible señalaba juicio en Isaías, las lenguas sin interpretación no edifican.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68264, 'spa', 'Yugo desigual', 'El testimonio uniforme entre idiomas (''unequally-yoked'' en inglés, ''en yugo desigual'' en español, ''atteler inégalement'' en francés) preserva la imaginería agrícola. La pregunta retórica de Pablo en 2 Corintios 6:14 emplea este hápax para cuestionar a los creyentes sobre la formación de alianzas vinculantes, ya sean comerciales, religiosas o matrimoniales, donde los valores fundamentales y las lealtades últimas divergen irreconciliablemente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68265, 'spa', 'otro, un adicional', 'El sentido amplio y no marcado: otro o una entidad adicional del mismo tipo general. Es la lectura predeterminada en 91 de 98 apariciones. En Mateo 6:24 contrasta dos amos; en Mateo 8:21 ''otro discípulo'' se presenta. Las glosas multilingües — español otro, francés autre, alemán anderer — se ajustan con precisión a este significado numéricamente aditivo sin implicar diferencia cualitativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68270, 'spa', 'diferente, distinto', 'El sentido cualitativamente marcado: diferente o distinto en naturaleza, no meramente adicional. Lucas 9:29 describe el rostro de Jesús volviéndose ''diferente'' en la transfiguración, y las alarmadas referencias de Pablo a ''otro espíritu'' y ''otro evangelio'' en 2 Corintios 11:4 dependen de este matiz. El español distingue diferente junto a otro, confirmando la escisión semántica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68276, 'spa', 'siguiente, próximo', 'Sentido temporal-secuencial: el siguiente (día, ocasión) en una serie. En Hechos 20:15 y 27:3 modifica un ''día'' implícito, dando ''al día siguiente.'' El español siguiente día muestra la transición de la otredad categórica a la sucesión cronológica, una extensión metafórica natural de ''el otro'' a ''el que sigue.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68282, 'spa', 'De manera diferente', 'Apareciendo únicamente en la discusión de Pablo sobre la madurez espiritual (Filipenses 3:15), este adverbio reconoce la diversidad de pensamiento dentro de la comunidad creyente. Las traducciones (''differently,'' ''diferentemente,'' ''anders'') capturan su significado directo, mientras que el contexto paulino sugiere que Dios mismo aclarará aquellos asuntos donde los creyentes ven las cosas desde ángulos distintos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68283, 'spa', 'todavía, aún', 'Continuidad temporal: «todavía, aún» — indica que un estado o acción persiste en el presente o futuro esperado. El alemán «noch», el francés «encore» y el coreano «아직» convergen en duración ininterrumpida. Destaca en transiciones narrativas como Mt 26:47 («estando él aún hablando») y Mt 17:5 («mientras él aún hablaba»).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68284, 'spa', 'ya no, no más', 'Continuidad negada: «ya no, no más» — cuando está regido por la negación (οὐκέτι, μηκέτι), el adverbio marca el cese de un estado previamente vigente. Las traducciones usan el adverbio base apoyándose en el contexto para la inversión. Pasajes clave: Lc 16:2 («ya no puedes ser mayordomo») y Heb 10:2 («ya no habría conciencia de pecados»).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68289, 'spa', 'preparar algo, disponer', 'preparar algo, disponer');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68294, 'spa', 'estar preparado, haber sido dispuesto', 'estar preparado, haber sido dispuesto');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68306, 'spa', 'prepararse a si mismo', 'prepararse a si mismo');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68309, 'spa', 'Disposición activa', 'El contexto militar de Efesios 6 otorga a esta disposición un matiz distintivo. Así como los soldados romanos mantenían sus sandalias preparadas para un despliegue rápido, los creyentes mantienen una preparación constante para proclamar la paz mediante el evangelio. Las traducciones (''readiness,'' ''preparación,'' ''Bereitschaft'') enfatizan consistentemente este estado de disponibilidad activa más que la mera posesión pasiva del equipo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68310, 'spa', 'Listo, preparado', 'Listo, preparado: en estado de preparación, el uso adjetival predominante. La cena de bodas está lista (Mateo 22:4), el aposento alto está dispuesto y preparado (Marcos 14:15), y los creyentes deben estar listos para el regreso del Hijo del Hombre (Mateo 24:44; Lucas 12:40). La palabra describe una condición objetiva de preparación completa, aplicada tanto a cosas como a personas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68311, 'spa', 'Disposición, preparación', 'Disposición, preparación: disposición como cualidad abstracta, usado sustantivamente en 2 Corintios 10:6, donde Pablo habla de estar «preparados para castigar toda desobediencia». Capta el paso de un estado concreto («la cena está lista») a una resolución interior o voluntad de actuar. Esta es la única aparición neotestamentaria donde el término funciona más como sustantivo que como adjetivo predicativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68312, 'spa', 'Dispuesto, preparado', 'Las traducciones emplean términos de disposición: en español «dispuesto» o «preparado», correspondientes a la forma adverbial griega ἑτοίμως. En Hechos 21:13 Pablo declara: «Estoy dispuesto no solo a ser encarcelado, sino incluso a morir en Jerusalén por el nombre del Señor Jesús.» En 2 Corintios 12:14 afirma estar listo para visitarlos, y en 1 Pedro 4:5 se advierte que rendirán cuentas ante aquel que está preparado para juzgar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68313, 'spa', 'año', 'Un ciclo anual completo como unidad para medir el tiempo prolongado en el Nuevo Testamento: la edad de una persona (Lc 2:42 «doce años»), la duración de una aflicción (Mc 5:25 «doce años»; Gá 1:18 «tres años») o la periodización histórica (Hch 7:6 «cuatrocientos años»; Heb 3:17 «cuarenta años»).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68316, 'spa', 'Bien, correctamente', 'Indica una acción o condición realizada de manera apropiada, correcta o moralmente justa. En Marcos 14:7 Jesús dice que los discípulos pueden hacer el bien a los pobres cuando quieran; en Efesios 6:3 la promesa es ''para que te vaya bien''. Refleja el sentido adverbial directo de rectitud o conveniencia moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68317, 'spa', '¡Bien hecho!', 'Exclamación de elogio — ''¡Bien hecho!'' — pronunciada por un señor o figura de autoridad para alabar el servicio fiel. Las tres apariciones se encuentran en la parábola de los talentos o las minas (Mt 25:21, 25:23, Lc 19:17). La fuerza intensificada y celebratoria distingue este uso del adverbio corriente: no es simplemente ''bien'' sino una declaración de aprobación solemne.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68320, 'spa', 'proclamar buenas nuevas', 'Proclamar o predicar activamente buenas nuevas, ya sea el reino de Dios o el evangelio en sentido amplio. Uso dominante (47 de 55 apariciones). «Anunciar buenas nuevas» y «Evangelium verkündigen» preservan la raíz de «buena noticia». Pasajes clave: Lc 4:18 (manifiesto de Jesús), Hch 8:35 (Felipe al etíope). La voz media subraya la implicación del heraldo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68325, 'spa', 'ser evangelizado, recibir buenas nuevas', 'Ser evangelizado — recibir la proclamación de buenas nuevas, en construcciones pasivas donde el sujeto es receptor. En Mt 11:5 y Lc 7:22 Jesús dice que «a los pobres se les anuncia el evangelio», haciendo de los destinatarios el foco gramatical. Hebreos 4:2 advierte que oír no basta; el mensaje debe mezclarse con fe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68349, 'spa', 'buenas nuevas, evangelio', 'Las buenas nuevas o evangelio — la acción salvífica de Dios proclamada por medio de Jesucristo. Empleado tanto como término general para las buenas noticias (Mt 4:23; 24:14) como designación semi-técnica del mensaje apostólico predicado a todas las naciones (Mc 1:1; Ro 1:16). Todas las lenguas lo vierten con un préstamo o calco directo del griego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68353, 'spa', 'Evangelista', 'Las traducciones emplean uniformemente formas de «evangelista». En Hechos 21:8 se identifica a «Felipe el evangelista, que era uno de los siete», distinguiéndolo por este título ministerial. Efesios 4:11 enumera los dones de Cristo a la iglesia: «los apóstoles, los profetas, los evangelistas, los pastores y maestros», marcando a los evangelistas como una categoría ministerial distinta. En 2 Timoteo 4:5 Pablo insta a Timoteo a cumplir esta labor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68354, 'spa', 'Agradar a Dios', 'Las traducciones emplean términos de complacencia: en español «agradar», en alemán «wohlgefallen» (ser grato). Hebreos 11:5 afirma que antes de su traslado, Enoc «recibió testimonio de haber agradado a Dios». Hebreos 11:6 declara el principio: «sin fe es imposible agradarle», estableciendo la fe como requisito indispensable de la aprobación divina. Hebreos 13:16 exhorta a la generosidad, pues «de tales sacrificios se agrada Dios».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68355, 'spa', 'Agradable, aceptable', 'Agradable o aceptable, describe la conducta, las ofrendas o las personas que genuinamente complacen y obtienen aprobación, casi siempre con Dios como aquel a quien se agrada. Pablo lo emplea para presentar el cuerpo como sacrificio vivo ''agradable a Dios'' (Ro 12:1) y discernir su voluntad (Ro 12:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68359, 'spa', 'Servicio agradable a Dios', 'El pasaje de Hebreos empareja este adverbio con reverencia y temor piadoso, mostrando que el servicio aceptable implica tanto la actitud correcta como la acción correcta. La evidencia multilingüe (''acceptably,'' ''agradablemente,'' ''wohlgefaellig'') subraya la noción de un servicio que complace. Es una adoración que Dios recibe con agrado porque honra su santidad y su gracia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68360, 'spa', 'Creyente romano fiel', 'Mencionado únicamente en los saludos finales de Pablo (2 Timoteo 4:21), Eubulo aparece junto a Pudente, Lino y Claudia como parte de la comunidad cristiana romana que permaneció leal a Pablo. El significado de su nombre (''bien aconsejado'') era común en el mundo grecorromano. Su inclusión en esta breve lista sugiere que era conocido por Timoteo, habiendo quizás enviado saludos o apoyo específico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68361, 'spa', 'Noble, distinguido', 'Las traducciones indican consistentemente nobleza: en español «noble» o «más nobles», en francés «noble» o «de noble race». Lucas 19:12 abre la parábola: «Un hombre noble se fue a un país lejano para recibir un reino.» Hechos 17:11 elogia a los bereanos como «más nobles que los de Tesalónica» porque examinaban las Escrituras diariamente. En 1 Corintios 1:26 Pablo señala la sabiduría inversa de Dios: «no muchos son nobles según la carne».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68362, 'spa', 'Buen tiempo atmosférico', 'Tiempo despejado y apacible, la condición atmosférica sin lluvia ni tormenta. En Mateo 16:2, Jesús contrasta εὐδία (buen tiempo) con χειμών (tormenta), usando la predicción meteorológica como lección sobre el discernimiento espiritual. Los fariseos podían leer el cielo rojo del atardecer y predecir εὐδία para el día siguiente, pero no lograban interpretar las señales de la era mesiánica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68363, 'spa', 'Expresa el deleite asentado y la aprobación de Dios o de una persona hacia algui', 'Expresa el deleite asentado y la aprobación de Dios o de una persona hacia alguien o algo. En el bautismo de Jesús (Mt 3:17) y en la transfiguración (Mt 17:5), la voz del Padre declara ''en quien me complazco'', empleando este sentido. Transmite una satisfacción profunda y aprobatoria, no un simple acuerdo. Abarca 16 de las 21 apariciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68365, 'spa', 'Se desplaza del deleite emocional a la voluntad deliberada', 'Se desplaza del deleite emocional a la voluntad deliberada: considerar algo bueno y resolverse a hacerlo. Pablo dice que los macedonios ''tuvieron a bien'' compartir sus recursos (Ro 15:26), y él mismo ''prefiere'' partir para estar con Cristo (2 Co 5:8). Este matiz volitivo distingue el consentimiento resuelto del mero agrado. Abarca 5 apariciones en las epístolas paulinas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68375, 'spa', 'Beneplácito, voluntad bondadosa', 'El propósito benévolo, el deleite soberano o la voluntad bondadosa de Dios (o de una persona), que denota la disposición favorable que motiva la acción. En sus nueve apariciones en el NT, se refiere predominantemente al beneplácito divino: su voluntad gozosa detrás de la salvación y la bendición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68384, 'spa', 'Hacer el bien', 'La descripción de Pedro sobre el ministerio de Jesús en Hechos 10:38 empareja este verbo con la sanidad, mostrando que hacer el bien tomaba forma tangible: liberar a los oprimidos por el diablo y sanar enfermedades físicas. Era beneficencia en su forma más pura: poder divino empleado para el florecimiento humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68385, 'spa', 'Bienhechores y patronos', 'El uso que Jesús hace de este término (Lucas 22:25) critica el sistema de patronazgo donde el poder político se disfrazaba de benevolencia. Mientras los gobernantes gentiles codiciaban el título de «bienhechor» (usado oficialmente por reyes helenísticos), el reino de Jesús invierte el esquema: la verdadera grandeza surge del servicio, no de instrumentalizar los dones para crear obligación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68386, 'spa', 'Apto o adecuado', 'Las traducciones emplean vocabulario de aptitud y utilidad: en español apto/útil, en francés apte. En Lucas 9:62 Jesús advierte solemnemente: «Ninguno que pone su mano en el arado y mira atrás es apto para el reino de Dios.» Lucas 14:35 describe la sal insípida como inútil, y Hebreos 6:7 bendice la tierra que produce fruto adecuado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68387, 'spa', 'inmediatamente, al instante', 'Adverbio temporal que expresa acción sin dilación ni intervalo, transmitiendo inmediatez y resolución, especialmente en intervenciones divinas y respuestas a la autoridad de Jesús. Característico del estilo ágil de Marcos, aparece en momentos cruciales: el descenso del Espíritu en el bautismo (Mt 3:16), la obediencia instantánea de los discípulos (Mt 4:20) y sanidades inmediatas (Mt 8:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68390, 'spa', 'Ánimo y alegría', 'Las traducciones recurren al vocabulario de ánimo y valor: en español tener ánimo/estar de buen ánimo, en francés être joyeux. En Hechos 27:22 Pablo anima durante el naufragio: «Os exhorto a tener buen ánimo», asegurando la supervivencia. Hechos 27:25 repite la exhortación, y Santiago 5:13 pregunta: «¿Está alguno alegre? Que cante alabanzas.»');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68393, 'spa', 'Recto, derecho, íntegro', 'Físicamente recto o nivelado, y por extensión moralmente íntegro o correcto. El uso dominante en el NT se apoya en Is 40:3, donde εὐθείας describe los senderos del Señor que deben ser enderezados, metáfora de la preparación espiritual proclamada por Juan el Bautista (Mt 3:3; Mr 1:3; Lc 3:4–5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68399, 'spa', 'Rectitud moral', 'La cita en Hebreos aplica el salmo real al Hijo, declarando que el gobierno divino opera con perfecta rectitud moral. A diferencia de los reinos humanos torcidos por la corrupción y el favoritismo, el cetro de Dios permanece inquebrantablemente recto, abarcando tanto la justicia judicial como la integridad personal que caracterizan el reinado mesiánico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68400, 'spa', 'Tener oportunidad', 'Las traducciones emplean vocabulario de oportunidad y tiempo: en español tener oportunidad/tener tiempo, en francés avoir le loisir/avoir le temps. Marcos 6:31 describe la intensa actividad de los discípulos: «No tenían tiempo ni para comer.» Hechos 17:21 caracteriza a los atenienses que «dedicaban todo su tiempo a contar o escuchar novedades», y 1 Corintios 16:12 señala que Apolos visitará «cuando tenga oportunidad».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68404, 'spa', 'Más fácil', 'Más fácil, más factible (grado comparativo). Cada aparición neotestamentaria se encuentra dentro de una comparación introducida por Jesús para cuestionar las suposiciones de sus oyentes. En los debates sobre sanación y perdón (Mt 9:5; Mr 2:9; Lc 5:23), εὐκοπώτερον establece la lógica de que la sanación visible demuestra el perdón invisible. En los dichos del camello y la aguja (Mt 19:24; Mr 10:25; Lc 18:25), subraya una imposibilidad humanamente insuperable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68406, 'spa', 'Temor reverente', 'El ejemplo de Noé (Hebreos 11:7) muestra el temor reverente traducido en acción concreta. Advertido sobre un juicio aún invisible, respondió con la seriedad apropiada: no paralizado por el miedo, sino movido a una preparación obediente. Este temor piadoso es productivo y está lleno de fe, no de pánico sino de reverencia activa ante la palabra de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68407, 'spa', 'Devoto y reverente', 'Devoto, reverente, genuinamente piadoso: describe a quien se acerca a Dios y a los deberes sagrados con reverencia esmerada y sincera. Simeón es llamado εὐλαβής mientras aguarda fielmente la consolación de Israel (Lc 2:25). Los judíos devotos de Pentecostés (Hch 2:5) y quienes sepultaron a Esteban (Hch 8:2) comparten esta cualidad. Ananías recibe el elogio de devoto por parte de la comunidad judía (Hch 22:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68408, 'spa', 'bendecir a alguien, pronunciar bendicion', 'bendecir a alguien, pronunciar bendicion');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68409, 'spa', 'bendito, en estado de bienaventuranza', 'bendito, en estado de bienaventuranza');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68411, 'spa', 'alabar, dar gracias a Dios', 'alabar, dar gracias a Dios');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68424, 'spa', 'Bendito, digno de alabanza', 'Digno de bendición y alabanza, aplicado como epíteto divino. A diferencia de μακάριος (dichoso, afortunado), εὐλογητός se reserva para Dios como receptor de la alabanza humana. Ancla las grandes doxologías: ''Bendito sea el Dios y Padre de nuestro Señor Jesucristo'' (2 Co 1:3; Ef 1:3; 1 P 1:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68427, 'spa', 'Bendición, acto de bendecir', 'Bendición, acto de bendecir: bendición como pronunciamiento de favor divino, estado de bienaventuranza o don concreto de Dios. Abarca las «bendiciones espirituales» de Efesios 1:3, la «bendición de Abraham» pactual (Gálatas 3:14), la «copa de bendición» eucarística (1 Corintios 10:16) y la generosidad abundante que Pablo alienta de los corintios (2 Corintios 9:5-6). En Hebreos, Isaac y Esaú contienden por la bendición patriarcal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68429, 'spa', 'Adulación, palabras suaves', 'Adulación, palabras suaves: adulación o palabras halagadoras usadas engañosamente, una amarga inversión del significado habitual de la palabra. En Romanos 16:18, Pablo advierte que ciertas personas «con palabras suaves y lisonjas (εὐλογία) engañan los corazones de los ingenuos». Aquí la «buena palabra» se convierte en arma retórica. La mayoría de traducciones luchan por señalar este giro semántico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68431, 'spa', 'Generosidad liberal', 'En la instrucción de Pablo a los ricos (1 Timoteo 6:18), esta cualidad acompaña el hacer buenas obras: quienes poseen abundancia material deben caracterizarse por la generosidad, compartiendo libremente en lugar de aferrarse a sus recursos. Esta generosidad sirve como antídoto contra el amor al dinero y demuestra una confianza puesta en Dios antes que en las riquezas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68432, 'spa', 'Madre fiel de Timoteo', 'Pablo (2 Timoteo 1:5) honra el legado de fe transmitido de Loida a Eunice y luego a Timoteo. Esta madre judeocristiana fundamentó a su hijo en las Escrituras desde la infancia (2 Timoteo 3:15), pese al trasfondo griego de su esposo. Su nombre, ''buena victoria'', resultó profético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68433, 'spa', 'Disposición conciliadora', 'La parábola legal de Jesús (Mateo 5:25) insta a reconciliarse rápidamente con el adversario antes de llegar al tribunal, donde los resultados pueden ser severos. El verbo enfatiza la disposición a resolver conflictos pacíficamente en vez de dejarlos escalar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68434, 'spa', 'Buena voluntad interior', 'La instrucción de Pablo a los siervos (Efesios 6:7) transforma el servicio cotidiano en adoración al reorientar el corazón hacia Cristo. No es optimismo ingenuo, sino alegría genuina arraigada en servir al Señor a través de cualquier labor, la disposición positiva que da vida al servicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68436, 'spa', 'Eunuco, oficial castrado', 'Varón castrado que servía como oficial de la corte o chambelán real, y por extensión alguien que vive en celibato voluntario. El sentido literal predomina en Hechos 8:27–39 con el eunuco etíope, funcionario de la reina Candace. Jesús en Mateo 19:12 amplía el término a eunucos de nacimiento, por intervención humana, y por elección voluntaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68438, 'spa', 'Colaboradora ministerial en Filipos', 'Pablo (Filipenses 4:2-3) trata a Evodia y Síntique como compañeras plenas de ministerio cuyo conflicto requería resolución urgente. Ambas habían ''combatido'' junto a él por el evangelio. El nombre aparece solo aquí, pero el llamado directo de Pablo revela su influencia en la comunidad filipense.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68439, 'spa', 'Prosperar o tener éxito', 'Prosperar, tener éxito o recibir un resultado favorable, originalmente referido a viajes y luego ampliado al bienestar general. Pablo emplea el sentido de travesía al pedir llegar a Roma por voluntad de Dios (Ro 1:10). En 1 Corintios 16:2 describe ganancia económica. Tercera de Juan 1:2 lo usa dos veces: para la salud física y para el florecimiento del alma, mostrando su plena extensión semántica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68440, 'spa', 'Docilidad razonable', 'En el contraste de Santiago entre sabiduría terrenal y celestial (3:17), ser ''dócil'' aparece junto a la pureza, la paz y la amabilidad. No es conformidad débil, sino humildad para considerar otras perspectivas y ceder cuando la verdad lo exige, sello de una sabiduría que edifica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68441, 'spa', 'Que enreda fácilmente', 'En la metáfora atlética de Hebreos (12:1), este adjetivo describe el pecado que se aferra a los corredores como ropa suelta, frenándolos en la carrera cristiana. El versículo anterior menciona la «gran nube de testigos» —santos fieles que corrieron bien— ahora espectadores de nuestra carrera. La evidencia multilingüe (''easily-entangling,'' ''que-fácilmente-rodea,'' ''leicht-umstrickend'') conserva la imagen de algo que se enrosca y estorba.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68442, 'spa', 'Beneficencia activa', 'Hebreos 13:16 empareja el hacer el bien con el compartir recursos, llamando a ambos «sacrificios» que agradan a Dios. Esto redefine la beneficencia como adoración, no en sustitución sino como complemento de la alabanza (v. 15). Las traducciones (''doing-good,'' ''beneficencia,'' ''Wohltun'') recalcan la bondad activa, la ayuda tangible prestada a otros. En la economía sacrificial de Hebreos, los actos generosos hacia el prójimo constituyen ofrendas aceptables.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68443, 'spa', 'Prosperar económicamente', 'La campaña de socorro de la iglesia de Antioquía (Hechos 11:29) muestra la generosidad cristiana primitiva respondiendo proporcionalmente a los recursos de cada uno. Quienes prosperaban o disponían de medios contribuían según su capacidad, estableciendo un modelo de ayuda mutua a través de fronteras geográficas. Las traducciones (''was-prospered,'' ''prosperaba,'' ''avoir-les-moyens'') apuntan coherentemente a recursos disponibles y capacidad económica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68444, 'spa', 'Prosperidad material', 'El discurso de Demetrio (Hechos 19:25) revela la prosperidad como poderoso motor de acción. La riqueza de los plateros provenía de fabricar santuarios de Artemisa, pero la predicación de Pablo ponía en peligro su lucrativo negocio al apartar a la gente de los ídolos. Las traducciones (''prosperity,'' ''prosperidad,'' ''prospérité'') enfatizan la abundancia material. Este episodio ilustra cómo los intereses económicos pueden avivar la oposición religiosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68445, 'spa', 'Belleza efímera', 'La metáfora botánica de Santiago (1:11) empareja este sustantivo con el marchitarse de la flor: antes hermosa, ahora ajada. La imagen evoca Isaías 40:6-8, donde la gloria humana se compara con la hierba que se seca. Las traducciones (''beauty,'' ''hermosura,'' ''Schoenheit'') resaltan el atractivo visible. Santiago advierte especialmente a los ricos: la belleza, el estatus y el esplendor terrenales son tan pasajeros como las flores silvestres.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68446, 'spa', 'Aceptable ante Dios', 'Aceptable, bien recibido, agradable — especialmente aquello que halla favorable acogida ante Dios. Las traducciones multilingües coinciden notablemente: español ''aceptable/bien aceptable'', francés ''agréable'' y alemán ''annehmbar'' apuntan al mismo concepto de aceptación voluntaria. En Rom 15:16 los creyentes gentiles son una ofrenda aceptable santificada por el Espíritu Santo. Rom 15:31 lo aplica al servicio de Pablo, y 2 Cor 6:2 proclama el tiempo aceptable de salvación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68447, 'spa', 'Devoción constante e indivisa', 'En la discusión de Pablo sobre el matrimonio y la soltería (1 Corintios 7:35), esta cualidad se presenta como una ventaja del estado célibe: poder ofrecer una atención constante e indivisa a la obra del Señor, sin las demandas legítimas pero inevitablemente divididas que conlleva la vida conyugal y familiar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68448, 'spa', 'Apariencia externa engañosa', 'La acusación de Pablo (Gálatas 6:12) expone el verdadero motivo de los judaizantes: hacer una exhibición externa impresionante para evitar la persecución por causa de la cruz. Al exigir la circuncisión, podían presentarse como observantes de la Torá, eludiendo la hostilidad de los opositores judíos. Pablo contrasta esto con su propia disposición a gloriarse solo en la cruz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68449, 'spa', 'hallar, descubrir', 'El sentido activo: hallar, encontrar o dar con algo buscándolo o por casualidad. Abarca la gran mayoría de apariciones: localizar personas (Mt 20:6, hallando obreros ociosos), objetos (Mt 13:44, un tesoro en el campo) o realidades abstractas (hallar descanso, hallar gracia). Se mueve con fluidez entre la búsqueda física y el descubrimiento cognitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68452, 'spa', 'ser hallado, ser descubierto', 'El sentido pasivo: ser hallado, ser descubierto, resultar o encontrarse en cierto estado. Se usa cuando el sujeto es lo descubierto y no el descubridor: María ''fue hallada'' encinta (Mt 1:18), el hijo perdido ''ha sido hallado'' (Lc 15:24, 32). A menudo con carga teológica: ser hallado digno, ser hallado en Cristo, o ser revelado en el juicio final.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68473, 'spa', 'obtener, conseguir', 'Sentido participial o especializado de obtener o asegurar algo mediante esfuerzo, como en Hebreos 9:12 donde se dice que Cristo ''obtuvo'' redención eterna. No se trata de encontrar algo por azar sino de lograrlo o procurarlo mediante acción deliberada, alineando εὑρίσκω con el sentido de adquisición intencionada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68499, 'spa', 'Viento tempestuoso del noreste', 'El detallado relato del naufragio de Lucas (Hechos 27:14) identifica este viento tempestuoso como la causa del desastre marítimo de Pablo. Surgiendo repentinamente desde la isla de Creta, empujó el barco hacia el suroeste a través del Mediterráneo durante catorce días de terror, hasta que finalmente encallaron en Malta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68500, 'spa', 'Amplio y espacioso', 'La enseñanza de Jesús sobre los dos caminos (Mateo 7:13) contrasta la vía espaciosa con el sendero angosto que lleva a la vida. La anchura del camino amplio simboliza su facilidad y popularidad: no requiere abnegación, no hay lucha contra la corriente, y ofrece abundante compañía. Pero esa espaciosidad atractiva resulta ser mortalmente engañosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68501, 'spa', 'Reverencia hacia Dios expresada mediante una vida fiel y recta — tanto la dispos', 'Reverencia hacia Dios expresada mediante una vida fiel y recta — tanto la disposición interior de devoción como su expresión exterior en la conducta. Central en las Epístolas Pastorales, donde aparece como la meta del ejercicio espiritual (1 Ti 4:7-8), el contenido de la sana doctrina (1 Ti 6:3) y una virtud que debe perseguirse activamente (1 Ti 6:11). En 2 Pedro 1:6-7 ocupa un lugar clave en la cadena de virtudes cristianas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68506, 'spa', 'Devoto y piadoso', 'Las traducciones emplean vocabulario de piedad: en español piadoso, en francés pieux, en alemán fromm. Hechos 10:2 presenta a Cornelio como «hombre piadoso y temeroso de Dios con toda su casa», definiendo su carácter antes de su conversión. Hechos 10:7 describe a uno de sus soldados como «devoto», y 2 Pedro 2:9 asegura que el Señor sabe librar de la prueba a los piadosos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68508, 'spa', 'Inteligible y comprensible', 'La discusión de Pablo sobre las lenguas (1 Corintios 14:9) insiste en la inteligibilidad dentro del culto congregacional. Hablar misterios en lenguas no interpretadas, por más genuinamente espiritual que sea, no edifica a la iglesia porque falta la claridad. El argumento de Pablo es pastoral: la adoración debe edificar al cuerpo a través de una comunicación clara.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68510, 'spa', 'Decoro y propiedad', 'Las traducciones emplean vocabulario de decoro: en español decorosamente, en francés décemment. Romanos 13:13 exhorta: «Andemos como de día, honestamente, no en orgías ni borracheras», contrastando la conducta decorosa con la vergonzosa. 1 Corintios 14:40 concluye las instrucciones sobre el culto: «Hágase todo decentemente y con orden.» 1 Tesalonicenses 4:12 insta a vivir decorosamente ante los de afuera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68511, 'spa', 'Decoro corporal', 'En la metáfora del cuerpo de Pablo (1 Corintios 12:23), este término describe las partes del cuerpo que carecen de dignidad o atractivo natural pero reciben cuidado y cobertura especial. Esto ilustra cómo la iglesia debe honrar a sus miembros menos prominentes con atención particular. Las traducciones como ''decoro'' y ''presentabilidad'' subrayan la respetabilidad y la propiedad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68512, 'spa', 'Honorable y prominente', 'Respetable, honorable, prominente — describe a personas de posición social distinguida o cosas que son presentables y dignas. Las traducciones al español ''distinguidas/decoroso'' y al francés ''honorable'' confirman el doble registro social y moral. En Mar 15:43, José de Arimatea es un miembro prominente del concilio. Hch 13:50 y 17:12 describen a mujeres y hombres influyentes en ciudades griegas. La metáfora corporal de Pablo en 1 Cor 12:24 aplica el término a los miembros presentables del cuerpo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68514, 'spa', 'Humor vulgar', 'En el catálogo de habla impropia de Pablo (Efesios 5:4), esta bufonada vulgar aparece junto a la inmoralidad sexual y la codicia, todas características de las tinieblas y no de la luz. El contraste es la acción de gracias, un hablar que honra a Dios y edifica al prójimo. Las traducciones como ''bufonada'' y ''necedad'' captan la cualidad degradante de este humor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68515, 'spa', 'Joven de Troas', 'El relato detallado de Lucas (Hechos 20:9-12) señala que Eutico cayó en un sueño profundo mientras Pablo predicaba pasada la medianoche en un aposento alto lleno de lámparas. Su caída de tres pisos lo mató, pero Pablo lo abrazó y declaró ''está vivo'', evocando los milagros de resurrección de Elías y Eliseo. El nombre ''el afortunado'' resultó finalmente apropiado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68516, 'spa', 'Reputación favorable', 'En el catálogo de paradojas ministeriales de Pablo (2 Corintios 6:8), esta buena fama se empareja con la calumnia: los apóstoles experimentan ambas según cambia la voluble opinión pública. Las traducciones como ''buena fama'' y ''buen informe'' enfatizan el hablar favorable y la reputación honrosa. Pablo enseña que la reputación externa, sea buena o mala, no define el ministerio genuino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68517, 'spa', 'Digno de elogio', 'Filipenses 4:8 presenta este término en un crescendo de virtudes que deben gobernar el pensamiento cristiano. Tras la verdad, la honra, la justicia, la pureza y la amabilidad viene esta cualidad de ser loable o encomiable. Las traducciones como ''de buena fama'' y ''digno de alabanza'' enfatizan lo que merece un buen informe. Pablo instruye a los creyentes a cultivar intencionalmente su vida mental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68518, 'spa', 'Producir abundantemente', 'En la parábola de Jesús (Lucas 12:16-21), una productividad excepcional se convierte en la trampa del rico insensato. Sus campos produjeron con tal abundancia que decidió construir graneros más grandes y acomodarse en una vida de autosuficiencia, pero Dios declaró que esa misma noche le sería requerida su alma. La ironía trágica es que la perfección agrícola desembocó en ruina espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68519, 'spa', 'Regocijarse, alegrarse o celebrar, usado intransitivamente en voz media o pasiva', 'Regocijarse, alegrarse o celebrar, usado intransitivamente en voz media o pasiva para personas que experimentan gozo o festividad. Domina en las parábolas lucanas de lo perdido: el repetido ''comamos y celebremos'' del padre (Lc 15:23-24) y la reprensión al hermano mayor, ''era necesario hacer fiesta y regocijarnos'' (Lc 15:32). También aparece en contextos escatológicos: Apocalipsis 18:20 invita al cielo a regocijarse.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68522, 'spa', 'Alegrar o causar gozo en otra persona, usado transitivamente en voz activa para ', 'Alegrar o causar gozo en otra persona, usado transitivamente en voz activa para describir el acto de producir alegría en alguien. La única aparición neotestamentaria se encuentra en la angustiada pregunta retórica de Pablo: ''Si yo os entristezco, ¿quién me alegrará?'' (2 Co 2:2). El paso de la celebración reflexiva a la alegría causativa es significativo — el gozo de Pablo depende de la salud espiritual de los corintios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68533, 'spa', 'dar gracias activamente', 'dar gracias activamente');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68548, 'spa', 'ser agradecido (pasiva)', 'ser agradecido (pasiva)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68550, 'spa', 'El acto o expresión de dar gracias a Dios, ya sea en la oración personal, en la ', 'El acto o expresión de dar gracias a Dios, ya sea en la oración personal, en la adoración corporativa o como actitud general de la vida cristiana. Pablo la hace compañera de la petición (Fil 4:6; Col 4:2) y el desbordamiento natural de experimentar la gracia de Dios (2 Co 4:15; 9:11-12). En 1 Corintios 14:16 denota una acción de gracias litúrgica que debe ser inteligible para la congregación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68554, 'spa', 'Agradecido, reconocido', 'La instrucción de Pablo (Colosenses 3:15) hace de la gratitud la corona de las virtudes que deben caracterizar a la comunidad creyente: después de que la paz gobierne los corazones, viene la gratitud como respuesta natural. No se trata de felicidad circunstancial, sino de un agradecimiento profundo arraigado en la gracia de Dios, un corazón reconocido incluso en medio de las dificultades.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68555, 'spa', 'Voto u oración', 'Las traducciones emplean lenguaje de voto y oración: español voto/oración, francés souhait. En Hechos 18:18 Pablo se corta el cabello porque estaba bajo un voto; en Hechos 21:23 se le aconseja unirse a cuatro hombres que tienen voto. Santiago 5:15 promete que la oración de fe sanará al enfermo, empleando el mismo término para una petición solemne.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68556, 'spa', 'Orar, pedir a Dios', 'Orar, elevar una petición a Dios o interceder por otros. Es el sentido predominante en el NT, presente en seis de siete ocurrencias. En Hechos 26:29 Pablo ora a Dios para que sus oyentes se conviertan; en 2 Corintios 13:7 y 13:9 ora por la integridad moral de los corintios; en Santiago 5:16 la oración del justo tiene gran eficacia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68557, 'spa', 'Desear intensamente', 'Desear con intensidad, expresando un anhelo personal profundo que puede ser hipotético o incluso contrario a la realidad. El único ejemplo claro en el NT es Romanos 9:3, donde Pablo escribe ηὐχόμην ἀνάθεμα εἶναι αὐτὸς ἐγώ —''deseaba ser yo mismo anatema''—. El tiempo imperfecto señala un deseo irrealizable, un recurso retórico conocido del griego clásico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68562, 'spa', 'Útil para servicio', 'Las traducciones señalan utilidad de manera uniforme: español útil, alemán nützlich. En 2 Timoteo 2:21 se habla de purificarse para llegar a ser un vaso útil al Señor. Filemón 11 juega con el nombre de Onésimo (que significa ''útil''): antes inútil, ahora provechoso tanto para Pablo como para Filemón. En 2 Timoteo 4:11 Pablo pide que traigan a Marcos porque le es útil para el ministerio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68563, 'spa', 'Cobrar ánimo', 'La esperanza expresada por Pablo (Filipenses 2:19) es que la visita de Timoteo y su posterior informe sobre los filipenses lo animen, literalmente, fortalezcan su alma. Esto refleja el profundo afecto del apóstol por esta iglesia y su anhelo de recibir buenas noticias sobre la perseverancia de ellos. El aliento aquí no es superficial, sino un fortalecimiento genuino del espíritu.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68564, 'spa', 'Aroma sacrificial', 'Las traducciones emplean lenguaje de fragancia: español fragancia, francés parfum, alemán Wohlgeruch. En 2 Corintios 2:15 Pablo dice que somos aroma de Cristo entre los que se salvan y los que se pierden. Efesios 5:2 presenta a Cristo como ofrenda fragante y sacrificio a Dios. Filipenses 4:18 describe el donativo como sacrificio aceptable y agradable, aplicando la imagen del aroma del templo a la generosidad cristiana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68565, 'spa', 'Izquierdo (lado)', 'Relativo al lado izquierdo o la mano izquierda, opuesto espacial de derecho (dexios). Las nueve apariciones neotestamentarias son posicionales: asientos en el reino (Mt 20:21,23; Mc 10:37,40), ubicacion de los condenados en el juicio final (Mt 25:33,41) y posicion de los crucificados junto a Jesus (Mt 27:38; Mc 15:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68568, 'spa', 'Abalanzarse violentamente', 'El desastre del exorcismo en Éfeso (Hechos 19:16) muestra el poder demoníaco aplastando a quienes intentan usurpar autoridad espiritual. Cuando los hijos de Esceva invocaron el nombre de Jesús sin una relación verdadera con él, el endemoniado se abalanzó sobre ellos con violencia sobrenatural, golpeándolos tan severamente que huyeron desnudos y heridos. El incidente subraya el peligro de manipular lo sagrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68569, 'spa', 'De una vez para siempre', 'De una vez para siempre, en una sola ocasión — enfatiza una acción única, definitiva e irrepetible. La expresión española ''de una vez para siempre'' y la alemana ''ein für allemal'' captan perfectamente la fuerza de finalidad. En Heb 7:27, la ofrenda de Cristo se contrasta con los sacrificios sacerdotales diarios; Heb 9:12 declara que entró en el lugar santísimo una vez para siempre con su propia sangre; Heb 10:10 fundamenta la santificación en esa ofrenda irrepetible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68570, 'spa', 'Gentilicio de Éfeso', 'Designa a una persona o cosa perteneciente a Éfeso. Las cinco apariciones se agrupan en Hch 19–21: el grito de los artesanos ''¡Grande es Artemisa de los efesios!'' (Hch 19:28, 34), el secretario de la ciudad dirigiéndose a la multitud como efesios (Hch 19:35), y la acusación contra Pablo por haber llevado a Trófimo el efesio al templo (Hch 21:29). Las traducciones lo tratan uniformemente como gentilicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68571, 'spa', 'Éfeso (nombre propio)', 'Éfeso (nombre propio): nombre propio de la ciudad principal de la provincia romana de Asia (actual Turquía occidental), significativa en el NT como centro de la actividad misionera de Pablo (Hechos 18:19-21; 19:1-41; 20:16-17), destinataria de una carta apostólica (Efesios 1:1), lugar de la asignación ministerial de Timoteo (1 Timoteo 1:3; 2 Timoteo 1:18; 4:12) y primera de las siete iglesias dirigidas en Apocalipsis (Apocalipsis 1:11; 2:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68572, 'spa', 'Inventores del mal', 'El sombrío retrato que Pablo traza de la humanidad bajo el juicio de Dios (Romanos 1:30) incluye esta cualidad perturbadora: no simplemente persistir en pecados heredados, sino inventar males nuevos. Esta creatividad en la corrupción revela la profundidad de la depravación cuando Dios entrega a las personas a una mente reprobada. Lejos de la mera imitación, es ingenio perverso al servicio de la rebelión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68574, 'spa', 'Necesidad diaria', 'El ejemplo hipotético de Santiago (2:15) sobre un hermano o hermana que carece de alimento diario ilustra una fe vacía que ofrece palabras piadosas sin ayuda práctica. Las traducciones (''diario'', ''cotidiano'', ''taeglich'') recalcan necesidades regulares y recurrentes, no artículos de lujo sino el sustento básico de cada día. El argumento de Santiago es contundente: la fe que no provee el pan diario a los creyentes hambrientos está muerta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68576, 'spa', 'Colocarse junto a alguien o cerca de él, permaneciendo en estrecha proximidad', 'Colocarse junto a alguien o cerca de él, permaneciendo en estrecha proximidad. Es el uso más frecuente en el NT: el ángel ''se presentó'' junto a los pastores (Lc 2:9) y los varones de blanco ''se pusieron junto a'' los apóstoles en la Ascensión. El sentido sugiere una presencia serena y deliberada, con disposición a actuar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68580, 'spa', 'Sobrevenir inesperadamente o aparecer de forma repentina, con un elemento de sor', 'Sobrevenir inesperadamente o aparecer de forma repentina, con un elemento de sorpresa. Lucas favorece este uso: Marta se ve abrumada por las exigencias del servicio (Lc 10:40), y el día del fin ''sobreviene'' a los desprevenidos (Lc 21:34). En Hch 4:1 y 6:12, las autoridades religiosas caen sobre los apóstoles sin aviso previo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68585, 'spa', 'Estar presente, a la mano o ser inminente como estado más que como acción', 'Estar presente, a la mano o ser inminente como estado más que como acción. Pablo escribe que su ''partida ha llegado'' (2 Ti 4:6), usando el perfecto para indicar una condición ya cumplida. En Hch 28:2, la lluvia ''se había establecido''. Este uso estativo se distingue de los sentidos 1 y 2 en que la llegada está completada y el énfasis recae sobre la condición resultante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68586, 'spa', 'Ser urgente, persistir o apremiar en el cumplimiento de un deber', 'Ser urgente, persistir o apremiar en el cumplimiento de un deber. En 2 Timoteo 4:2, Pablo encarga a Timoteo que ''insista'' — que esté en su puesto, que persista sea oportuno o no. Este sentido extiende el ''estar encima'' espacial hacia la vigilancia figurada y la disposición incansable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68591, 'spa', 'Lanzarse sobre alguien con intención hostil, asaltar o atacar', 'Lanzarse sobre alguien con intención hostil, asaltar o atacar. En Hch 17:5, la turba celosa ''se presentó ante'' la casa de Jasón buscando a Pablo y Silas. Este uso marcial aprovecha el sentido del compuesto de imponerse a la fuerza sobre otro, pasando de la mera aparición a la confrontación agresiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68593, 'spa', 'Refugio de Jesús', 'Juan registra (11:54) que, tras resucitar a Lázaro —el milagro que selló la determinación de las autoridades de matar a Jesús—, este se retiró a este pueblo del desierto durante un tiempo. El lugar ofrecía distancia estratégica de la hostilidad de Jerusalén mientras permanecía lo suficientemente cerca para el viaje pascual. El nombre Efraín conecta con la historia de Israel, pero su relevancia bíblica reside exclusivamente en haber proporcionado refugio temporal a Jesús.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68594, 'spa', 'Mandato de sanación', 'La preservación por parte de Marcos de la palabra aramea de Jesús (7:34) intensifica la vivacidad de la escena: escuchamos las sílabas mismas que Jesús pronunció. El mandato no se dirigía solo a los oídos del hombre, sino al bloqueo completo que impedía la comunicación. El suspiro de Jesús sugiere el peso de vivir en un mundo caído donde tales aflicciones existen. Las traducciones simplemente transliteran el arameo, ya que Marcos proporciona la traducción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68595, 'spa', 'Enemistad, hostilidad', 'Enemistad, hostilidad o antagonismo profundo entre personas o grupos, abarcando desde rivalidades interpersonales hasta la oposición espiritual cósmica. En Romanos 8:7 describe la mentalidad carnal como enemistad contra Dios; en Efesios 2:15-16 Cristo destruye el muro divisorio de enemistad entre judío y gentil; en Gálatas 5:20 aparece entre las obras de la carne junto con los celos y las discordias. Lucas 23:12 la usa para la enemistad personal entre Herodes y Pilato.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68598, 'spa', 'enemigo, adversario hostil', 'enemigo, adversario hostil');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68601, 'spa', 'Serpiente venenosa', 'Serpiente venenosa usada tanto literal como figuradamente. En su uso figurado, la frase γεννήματα ἐχιδνῶν (''generación de víboras'') aparece en Mat 3:7, 12:34, 23:33 y Luc 3:7, donde Juan el Bautista y Jesús la emplean como severa reprensión moral, sugiriendo maldad heredada y peligro espiritual mortal. La única aparición literal (Hch 28:3) describe la serpiente que muerde a Pablo en Malta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68602, 'spa', 'tener/poseer', 'Posesión o propiedad de objetos materiales, cualidades, o derechos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68624, 'spa', 'poder/ser capaz', 'Tener la capacidad, habilidad u oportunidad de hacer algo; estar en posición de.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68638, 'spa', 'estar en un estado', 'Encontrarse en una condición física, emocional o circunstancial particular; experimentar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68643, 'spa', 'sostener/guardar', 'Mantener en la mano o bajo control; sujetar, retener, conservar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68645, 'spa', 'estar adyacente/relacionado', 'Tener una relación o conexión cercana con algo o alguien; estar vinculado a.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68706, 'spa', 'hasta', 'La conjunción temporal ''hasta,'' que marca el punto final o el límite al que se extiende una acción. Abarca 143 apariciones incluyendo los marcadores genealógicos de Mateo 1:17 (''desde Abraham hasta David... hasta la deportación... hasta el Cristo'') y Mateo 1:25 (''hasta que dio a luz un hijo''). Las glosas multilingües son notablemente uniformes: español hasta, francés jusqu''à, alemán bis.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68707, 'spa', 'mientras', 'Un uso menos frecuente (4 apariciones) que significa ''mientras,'' expresando duración continua en lugar de un punto terminal. En Mateo 5:25 insta a reconciliarse con el adversario ''mientras estás en el camino,'' y en Marcos 14:32 Jesús dice a los discípulos que se sienten ''mientras yo oro.'' El español mientras separa claramente este sentido del hasta del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68710, 'spa', 'Tribu de Zabulón', 'El nombre aparece de forma uniforme como Zabulón. Mateo 4:13 señala que Jesús fue a vivir a Capernaúm, en territorio de Zabulón y Neftalí. Mateo 4:15 cita a Isaías: ''tierra de Zabulón y tierra de Neftalí... el pueblo que habitaba en tinieblas vio gran luz''. Apocalipsis 7:8 incluye doce mil sellados de la tribu de Zabulón, confirmando su lugar permanente en la identidad del pueblo de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68711, 'spa', 'Publicano de Jericó', 'Nombre propio del jefe de publicanos en Jericó que hospedó a Jesús y prometió dar la mitad de sus bienes a los pobres y devolver cuatro veces lo defraudado. Lucas emplea el nombre tres veces en rápida sucesión (19:2, 5, 8), construyendo la narración en torno a este individuo. Como transliteración del hebreo זַכַּי (cf. Nehemías 7:14), el nombre portaba asociaciones de pureza que habrían resultado irónicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68712, 'spa', 'Antepasado genealógico', 'La genealogía de Mateo (1:3) incluye a Zera junto a su gemelo Fares, algo inusual ya que las genealogías suelen listar solo la línea directa. Esta inclusión destaca el escandaloso episodio de Tamar y muestra que la elección soberana de Dios determinó la línea mesiánica a través de Fares, no de Zera, pese a la breve ventaja de este último en el orden de nacimiento. El nombre, que significa ''amanecer'', resultó irónico: Zera surgió primero pero fue eclipsado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68713, 'spa', 'Zacarías el sacerdote, padre de Juan el Bautista — un anciano sacerdote levítico', 'Zacarías el sacerdote, padre de Juan el Bautista — un anciano sacerdote levítico de la división de Abías, esposo de Elisabet. Mientras servía su turno sacerdotal en el templo, el ángel Gabriel anuncia el nacimiento de Juan; Zacarías duda y queda mudo hasta la circuncisión del niño, cuando profetiza el Benedictus (Lucas 1:5-67). Lucas 3:2 identifica a Juan por patronímico como ''hijo de Zacarías''. También se refiere al profeta Zacarías hijo de Berequías, mencionado por Jesús en Mateo 23:35 y Lucas 11:51.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68714, 'spa', 'estar vivo, tener vida', 'Estar en estado de vida física o espiritual, tener vida: el sentido nuclear abrumadoramente dominante con 133 apariciones. Abarca el Dios viviente (Mt 16:16; 26:63), las criaturas vivas, las personas vivas en contraste con los muertos y el poder vivificante de la palabra de Dios (''No solo de pan vivirá el hombre,'' Mt 4:4; Lc 4:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68728, 'spa', 'volver a vivir, resucitar', 'Volver a vivir, revivir tras haber muerto: 4 apariciones que marcan la dramática transición de la muerte a la existencia renovada. En Lucas 15:32 el pródigo ''estaba muerto y ha revivido''; en Romanos 14:9 Cristo ''murió y volvió a vivir''; en Apocalipsis 2:8 el Cristo resucitado ''estuvo muerto y volvió a la vida.'' El aoristo (ἔζησεν) capta el momento puntual de la resurrección.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68732, 'spa', 'vivir, conducir la vida', 'Vivir en el sentido de conducir la existencia terrenal a lo largo del tiempo: 4 apariciones centradas en la duración, la manera o las circunstancias de una vida vivida. Ana la profetisa ''vivió con su marido siete años'' (Lc 2:36); Pablo testifica que ''viví como fariseo'' (Hch 26:5); los mártires ''vivieron y reinaron con Cristo mil años'' (Ap 20:4-5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68753, 'spa', 'El nombre propio Zebedeo, referido a un pescador galileo y padre de los apóstole', 'El nombre propio Zebedeo, referido a un pescador galileo y padre de los apóstoles Jacobo y Juan. Aparece casi exclusivamente en frases patronímicas — ''Jacobo de Zebedeo'', ''los hijos de Zebedeo'' — sirviendo para identificar a estos dos apóstoles más que para caracterizar al propio Zebedeo. Presente en la escena del llamamiento junto al mar de Galilea (Mt 4:21; Mr 1:19-20) y referenciado indirectamente a través de su esposa (Mt 20:20; 27:56).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68757, 'spa', 'Caliente, ardiente', 'Todas las traducciones lo vierten como temperatura alta: en español «caliente», en alemán «heiss». Apocalipsis 3:15 dice: «Conozco tus obras: no eres ni frío ni caliente. ¡Ojalá fueras frío o caliente!» El versículo 16 añade: «Porque eres tibio, y no frío ni caliente, te vomitaré de mi boca.» La triple repetición subraya el contraste entre compromiso pleno y tibieza espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68759, 'spa', 'Amarras del timón', 'La única aparición neotestamentaria se encuentra en el vívido relato del naufragio, donde los marineros preparan la varada del barco soltando el mecanismo del timón. La evidencia interlingüística muestra que los traductores luchan con el vocabulario técnico marítimo, optando algunos por ''amarras'' o ''bandas'' y otros por transliteraciones. La asignación al dominio ANIMALES refleja el sentido clásico de la palabra relativo al uncimiento de animales, mientras que el uso neotestamentario es netamente náutico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68762, 'spa', 'Celo, devoción ardiente', 'Celo, devoción ardiente: celo, devoción ardiente o compromiso apasionado, el polo positivo de la misma intensidad emocional, ahora dirigida hacia Dios, una causa o una comunidad. Los discípulos recuerdan el Salmo 69:9 («El celo de tu casa», Juan 2:17), Israel tiene un «celo de Dios» mal encaminado pero genuino (Romanos 10:2), y los corintios muestran afán celoso por apoyar la colecta de Pablo (2 Corintios 7:11; 9:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68763, 'spa', 'Celos, envidia', 'Celos, envidia: celos, envidia o resentimiento rivalista, el polo negativo de la intensidad apasionada dirigida contra la ventaja o amenaza percibida de otro. Los saduceos están «llenos de celos» contra los apóstoles (Hechos 5:17), judíos en Antioquía están «llenos de celos» ante el éxito de Pablo (Hechos 13:45), y Pablo enumera los celos junto con contiendas y discordias como obras de la carne (1 Corintios 3:3; Gálatas 5:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68765, 'spa', 'Furia, indignación ardiente', 'Furia, indignación ardiente: furia, indignación o intensidad colérica, el extremo del espectro emocional, usado del juicio divino. Una única pero poderosa aparición en Hebreos 10:27 describe «un ardor de fuego que consumirá a los adversarios», donde ζῆλος intensifica la ya aterradora imagen del juicio escatológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68767, 'spa', 'Búsqueda positiva y enérgica de algo digno — ser celoso, aspirar con ardor', 'Búsqueda positiva y enérgica de algo digno — ser celoso, aspirar con ardor. La exhortación de Pablo a ''procurar los dones mejores'' (1 Co 12:31) y ''ser diligentes en profetizar'' (1 Co 14:39) ejemplifican este sentido. En Gálatas 4:17-18 Pablo distingue el celo bueno del celo manipulador, señalando que ''bueno es ser celado en lo bueno''. El español ''anhelad'' (desear ardientemente) y ''sé celoso'' captan bien este matiz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68768, 'spa', 'Respuesta emocional negativa de celos, envidia o codicia dirigida hacia otra per', 'Respuesta emocional negativa de celos, envidia o codicia dirigida hacia otra persona. Los patriarcas ''tuvieron envidia'' de José y lo vendieron a Egipto (Hch 7:9); ciertos judíos en Tesalónica ''se llenaron de celos'' e incitaron un tumulto (Hch 17:5). La famosa declaración de Pablo de que ''el amor no tiene envidia'' (1 Co 13:4) usa precisamente esta palabra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68776, 'spa', 'Persona celosa, devoto', 'Persona fervientemente comprometida con una causa o forma de vida. Pablo se declara ''celoso de las tradiciones de mis padres'' (Ga 1:14); miles en Jerusalen son ''celosos de la ley'' (Hch 21:20); Tit 2:14 exhorta a ser ''celosos de buenas obras''; y 1 Co 14:12 lo aplica a los dones espirituales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68780, 'spa', 'Zelote (epiteto de Simon)', 'Epiteto propio aplicado al apostol Simon, uno de los Doce, para distinguirlo de Simon Pedro. Aparece como ''Simon el Zelote'' (Simon ho Zelotes) en Lc 6:15 y Hch 1:13, correspondiendo a ''el Cananista'' (ho Kananaios) en Mateo y Marcos, del arameo qan''ana (''celoso''), no de ''Canaan''. Puede indicar pertenencia al movimiento zelote anti-romano o simplemente una intensa devocion religiosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68783, 'spa', 'Pérdida o menoscabo', 'Pérdida, daño o menoscabo: la experiencia de verse privado de algo valioso, ya sea material o abstracto. En el relato del naufragio, Pablo advierte sobre la pérdida de carga y vidas (Hch 27:10) y luego recuerda que el daño era previsible (Hch 27:21). Filipenses 3:7-8 transforma el vocablo en metáfora teológica: Pablo considera todas sus credenciales religiosas previas como ''pérdida'' frente al conocimiento de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68784, 'spa', 'Sufrir pérdida, perder', 'Sufrir pérdida, ser perjudicado o quedar privado de algo valioso, siempre en voz pasiva en el NT, describiendo la experiencia de perder algo como consecuencia o penalidad. La triple tradición sinóptica pregunta de qué sirve ganar el mundo entero si se pierde el alma (Mt 16:26, Mr 8:36, Lc 9:25). En 1 Corintios 3:15, un constructor cuya obra es consumida sufre pérdida, aunque él mismo se salva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68790, 'spa', 'Nombre propio personal', 'Pablo menciona a Zenas junto a Apolos en sus instrucciones a Tito, pidiendo provisiones generosas para ambos viajeros. La designación ''abogado'' (νομικός) sugiere pericia en la ley judía o romana. La evidencia multilingüe confirma su tratamiento universal como nombre propio. La única referencia en Tito 3:13 no ofrece más datos sobre su persona.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68791, 'spa', 'buscar, procurar hallar', 'Búsqueda física y concreta: buscar, intentar localizar a una persona, lugar o cosa. El espíritu inmundo ''busca'' reposo (Mt 12:43), los hombres de Herodes ''buscan'' la vida del niño (Mt 2:20), y la familia de Jesús lo ''busca'' entre la multitud (Mt 12:46-47). Es el sentido más tangible, que implica esfuerzo real por encontrar algo actualmente desconocido o perdido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68793, 'spa', 'desear, procurar obtener', 'Búsqueda volitiva y abstracta: desear, esforzarse por, perseguir algo a menudo intangible — gloria, señales, oportunidad o el reino de Dios. El mandato programático de Jesús ''buscad primeramente su reino'' (Mt 6:33) y la promesa ''buscad y hallaréis'' (Mt 7:7) operan en este registro. El objeto no está perdido sino que es valorado y perseguido activamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68815, 'spa', 'ser requerido, demandado', 'Voz pasiva: ser requerido, demandado o exigido de alguien, expresando obligación o rendición de cuentas. Lucas 12:48 (''al que se le confió mucho, mucho se le demandará'') y 1 Corintios 4:2 (''se requiere de los administradores que sean fieles'') son pasajes clave. El español pasa a es requerido y será demandado, revelando cómo la pasiva transforma el verbo de búsqueda en un verbo de exigencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68826, 'spa', 'Cuestión disputada', 'Punto de controversia o asunto contencioso, especialmente en debate jurídico o teológico. Las cinco apariciones neotestamentarias se hallan en Hechos: la controversia sobre la circuncisión enviada a Jerusalén (Hch 15:2), el rechazo de Galión al considerarlo cuestión de la ley judía (Hch 18:15), la evaluación de Lisias sobre cargos relativos a la ley judía (Hch 23:29), la perplejidad de Festo ante cuestiones sobre Jesús (Hch 25:19) y el debate ante Agripa (Hch 26:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68827, 'spa', 'Controversia, disputa', 'Controversia o cuestion debatida, especialmente sobre ley judia o doctrina religiosa. Jn 3:25 introduce una ''disputa'' sobre purificacion; Hch 15:2,7 la emplean para el debate sobre la circuncision en el Concilio de Jerusalen; y las Epistolas Pastorales (1 Ti 1:4; 6:4; 2 Ti 2:23; Tit 3:9) advierten contra ''controversias necias'' que generan contiendas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68829, 'spa', 'Indagacion, investigacion', 'Indagacion o investigacion formal, conservando el sentido clasico de busqueda judicial o administrativa de la verdad. En Hch 25:20, el gobernador romano Festo explica al rey Agripa que ''estaba perplejo respecto a la investigacion (zetesis) de estas cosas'', refiriendose al examen legal de los cargos presentados contra Pablo por las autoridades judias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68832, 'spa', 'Cizana, mala hierba', 'Cizana (Lolium temulentum), planta toxica que imita al trigo en su fase de crecimiento. Aparece exclusivamente en la parabola de Mt 13:25-40, donde un enemigo siembra ζιζάνια entre el trigo. Los siervos las descubren tras brotar ambas (v. 26), y el amo prohibe arrancarlas para no destruir el trigo (v. 29), detalle arraigado en la realidad botanica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68833, 'spa', 'Nombre personal', 'El nombre aparece de forma uniforme como Zorobabel. Mateo 1:12 registra: «Después de la deportación a Babilonia, Jeconías engendró a Salatiel, y Salatiel a Zorobabel.» Mateo 1:13 continúa: «Zorobabel engendró a Abiud.» Lucas 3:27 lo incluye en la genealogía ascendente. Estas referencias establecen la descendencia legal de Jesús a través de la línea davídica que pasó por el crisol del exilio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68834, 'spa', 'Tinieblas del juicio', 'Lobreguez infernal u oscuridad profunda, especialmente asociada con el juicio divino y la morada de los condenados. En Heb 12:18 describe la oscuridad aterradora del Sinaí; en 2 Pe 2:4 nombra las cadenas de tinieblas donde los ángeles caídos están retenidos; en 2 Pe 2:17 y Jud 1:13 es la más densa oscuridad reservada para los falsos maestros; y Jud 1:6 presenta el encarcelamiento angélico en términos paralelos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68835, 'spa', 'Yugo de obligación', 'Yugo de obligación, servidumbre o discipulado: la carga metafórica puesta sobre el cuello de alguien. Jesús ofrece su yugo suave (Mt 11:29-30); el concilio de Jerusalén rechaza imponer a los gentiles un yugo insoportable (Hch 15:10); los esclavos sirven bajo el yugo (1 Ti 6:1). La metáfora de autoridad impuesta es universalmente comprendida en todas las lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68836, 'spa', 'Balanza, instrumento de pesar', 'Par de balanzas: el travesaño del que cuelgan los platillos para pesar. En Apocalipsis 6:5 el tercer jinete sostiene un ζυγόν, anunciando precios de granos durante la hambruna. El español «balanza» distingue este sentido de medición comercial de la metáfora de servidumbre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68837, 'spa', 'Yugo de esclavitud', 'El yugo de esclavitud del que Cristo ha liberado a los creyentes, un uso específicamente liberador. En Gálatas 5:1 Pablo advierte contra someterse de nuevo a un «yugo de servidumbre». Este sentido está estrechamente relacionado con el sentido 1, pero porta la teología paulina distintiva de la libertad en Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68838, 'spa', 'Levadura', 'Levadura: sustancia fermentadora, ya sea levadura o masa madre, usada tanto literalmente para la elaboración de pan como figuradamente para cualquier influencia que se propaga silenciosamente, ya sea corruptora (Mt 16:6, 11-12; Mr 8:15; Lc 12:1; 1 Co 5:6-8; Gá 5:9) o vivificante (Mt 13:33; Lc 13:21). Las traducciones uniformes en distintos idiomas (francés levain, alemán Sauerteig, español levadura) reflejan la unidad de este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68840, 'spa', 'Leudar o fermentar', 'Leudar o hacer fermentar, describiendo cómo la levadura impregna y transforma completamente la masa. En las parábolas de Jesús (Mt 13:33; Lc 13:21) el verbo ilustra el poder transformador oculto pero total del reino: una mujer mezcla levadura en la harina hasta que toda la masa queda leudada. Pablo usa la misma imagen negativamente (1 Co 5:6; Gá 5:9), advirtiendo que tolerar un poco de corrupción moral infectará a toda la comunidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68842, 'spa', 'de vida, vital', 'Vida en su sentido más pleno: existencia biológica, vitalidad, y — especialmente en el uso teológico neotestamentario — la cualidad de vida divina y eterna otorgada mediante la relación con Dios en Cristo. Los escritos de Juan concentran este significado con mayor intensidad: «en él estaba la vida, y la vida era la luz de los hombres» (Jn 1:4). Pablo opone ζωή a la muerte como paga del pecado (Ro 6:23). Funciona como genitivo cualitativo: «agua de vida», «pan de vida».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68845, 'spa', 'Cinturon, cinto, faja', 'Cinturon o faja con funciones practicas, profeticas y simbolicas. El cinto de cuero del Bautista (Mt 3:4; Mc 1:6) evoca a Elias (2 Re 1:8). Jesus prohibe llevar dinero en el cinturon (Mt 10:9; Mc 6:8). Agabo usa el de Pablo como profecia actuada (Hch 21:11), y las fajas doradas de Apocalipsis (Ap 1:13; 15:6) elevan la prenda.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68849, 'spa', 'Ceñirse, prepararse', 'Las traducciones emplean vocabulario de ceñir: en español «cíñete» y «te ceñías», en francés «ceindre». Juan 21:18 contiene la conmovedora profecía de Jesús: «Cuando eras joven, te ceñías tú mismo e ibas adonde querías; pero cuando seas viejo, extenderás tus manos y otro te ceñirá y te llevará adonde no quieras», presagiando el martirio de Pedro. Hechos 12:8 recoge la orden del ángel para la liberación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68850, 'spa', 'Vivificar, preservar', 'Este sentido abarca tanto la preservación como la vivificación: mantener vivo lo que podría morir e impartir la vida misma. Las tres apariciones neotestamentarias comprenden la enseñanza paradójica de Jesús sobre perder la vida para salvarla, la opresión histórica de Israel en Egipto y la confesión doxológica del poder vivificante de Dios. Las glosas multilingües se agrupan en torno a «dar vida» y «mantener con vida».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68851, 'spa', 'Los cuatro seres vivientes celestiales alrededor del trono de Dios en Apocalipsi', 'Los cuatro seres vivientes celestiales alrededor del trono de Dios en Apocalipsis — el plural ζῷα describe a los seres querúbicos de los capítulos 4-5 que adoran sin cesar diciendo ''Santo, santo, santo''. Aparecen con seis alas y llenos de ojos (Ap 4:6-8), se postran ante el Cordero (5:8, 14) y anuncian a los jinetes (6:1-7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68852, 'spa', 'Un ser viviente celestial individual — los mismos seres del Apocalipsis referido', 'Un ser viviente celestial individual — los mismos seres del Apocalipsis referidos en singular, como cuando se describe a cada uno de los cuatro por separado (Ap 4:7, con rostro de león, de buey, de hombre y de águila) o cuando uno habla al abrirse cada sello (Ap 6:3, 5, 7). La forma singular centra la atención en la identidad distintiva de cada criatura dentro del grupo cuádruple.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68853, 'spa', 'Animal en el sentido zoológico ordinario — cualquier ser vivo, especialmente irr', 'Animal en el sentido zoológico ordinario — cualquier ser vivo, especialmente irracional o no humano. Hebreos 13:11 habla de animales de sacrificio cuya sangre es llevada al santuario; 2 Pedro 2:12 compara a los falsos maestros con ζῷα irracionales nacidos para ser capturados y destruidos; Judas 10 retoma esta comparación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68856, 'spa', 'Dar vida, vivificar', 'Dar vida, vivificar. Dar vida, vivificar — el sentido activo del poder divino que otorga vida, conferido por el Padre, el Hijo o el Espíritu sobre los muertos, los mortales o los espiritualmente inertes. Este sentido primario (8 ocurrencias) ancla algunas de las declaraciones teológicas más profundas del NT: el Padre y el Hijo conjuntamente ''dan vida'' a los muertos (Juan 5:21), el Espíritu ''da vida'' donde la carne no puede (Juan 6:63).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68857, 'spa', 'Ser vivificado, ser resucitado', 'Ser vivificado, ser resucitado. Ser vivificado, ser resucitado a vida — la voz pasiva que indica recepción de vida en lugar de su otorgamiento, especialmente en contextos de resurrección. Este sentido (3 ocurrencias) lleva un peso escatológico inmenso: ''en Cristo todos serán vivificados'' (1 Corintios 15:22) establece el alcance universal de la esperanza de resurrección; la analogía de la semilla en 1 Corintios 15:36 (''lo que siembras no es vivificado a menos que muera'') refuerza el principio de muerte antes de vida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68866, 'spa', 'o (disyuntiva)', 'La conjunción disyuntiva «o», que presenta dos o más alternativas. Este sentido abrumadoramente dominante (313 de 352 apariciones) se traduce de forma uniforme en todas las lenguas: alemán oder, francés ou, español «o». Se emplea tanto en construcciones simples de alternativa (Mt 5:17; 6:24) como en cadenas de múltiples opciones. Su lógica es transparente y universal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (68867, 'spa', 'que (comparativa)', 'La conjunción comparativa «que», que aparece tras adjetivos o adverbios comparativos (39 apariciones). La evidencia interlingüística resulta especialmente reveladora: mientras el francés ou y el alemán oder conservan la misma forma que la disyuntiva, el español emplea la partícula distinta «que» y el árabe despliega la preposición min, confirmando una distinción semántica genuina. Pasajes clave incluyen Mt 10:15 y 18:8-9.');